import { useState } from 'react'
import {
  BookOpen,
  Sparkles,
  ListChecks,
  CheckCircle2,
  Check,
  Clock,
  HelpCircle,
  Copy,
  Trash2,
  ExternalLink,
  X,
  FileText,
  Loader2,
} from 'lucide-react'

/**
 * Meeting Notes Card — Fourth Section of the Main Workspace.
 * Displays structured meeting notes generated by Groq LLM:
 * - Meeting Summary
 * - Key Discussion Points
 * - Decisions Made
 * - Action Items (readable table with Task, Owner, Deadline)
 * - Open Questions
 */
export default function MeetingNotesCard({
  notes = [],
  activeNote = null,
  isGenerating = false,
  onDeleteNote,
}) {
  const [copied, setCopied] = useState(false)
  const [viewingRawModal, setViewingRawModal] = useState(false)

  // Resolve note data: either activeNote object, or latest item in notes array
  const rawNoteObj = activeNote || (notes.length > 0 ? notes[0] : null)

  let structuredData = null
  let markdownText = ''

  if (rawNoteObj) {
    if (rawNoteObj.notes && typeof rawNoteObj.notes === 'object') {
      structuredData = rawNoteObj.notes
    } else if (rawNoteObj.meeting_summary || rawNoteObj.key_discussion_points) {
      structuredData = rawNoteObj
    } else if (rawNoteObj.content) {
      try {
        structuredData = JSON.parse(rawNoteObj.content)
      } catch {
        structuredData = null
      }
    }
    markdownText = rawNoteObj.markdown || rawNoteObj.content || ''
  }

  const meetingSummary =
    structuredData?.meeting_summary ||
    (typeof structuredData === 'string' ? structuredData : '')
  const keyPoints = Array.isArray(structuredData?.key_discussion_points)
    ? structuredData.key_discussion_points
    : []
  const decisions = Array.isArray(structuredData?.decisions_made)
    ? structuredData.decisions_made
    : []
  const actionItems = Array.isArray(structuredData?.action_items)
    ? structuredData.action_items
    : []
  const openQuestions = Array.isArray(structuredData?.open_questions)
    ? structuredData.open_questions
    : []

  const hasAnyData =
    Boolean(meetingSummary) ||
    keyPoints.length > 0 ||
    decisions.length > 0 ||
    actionItems.length > 0 ||
    openQuestions.length > 0 ||
    Boolean(markdownText && markdownText !== 'Loading notes from S3...')

  const handleCopyNotes = async () => {
    let textToCopy = markdownText
    if (!textToCopy && structuredData) {
      const parts = []
      if (meetingSummary) parts.push(`## Meeting Summary\n${meetingSummary}\n`)
      if (keyPoints.length > 0) parts.push(`## Key Discussion Points\n${keyPoints.map((p) => `- ${p}`).join('\n')}\n`)
      if (decisions.length > 0) parts.push(`## Decisions Made\n${decisions.map((d) => `- ${d}`).join('\n')}\n`)
      if (actionItems.length > 0) {
        parts.push(
          `## Action Items\n| Task | Owner | Deadline |\n| --- | --- | --- |\n${actionItems
            .map((item) => `| ${item.task || item} | ${item.owner || 'Not specified'} | ${item.deadline || 'Not specified'} |`)
            .join('\n')}\n`
        )
      }
      if (openQuestions.length > 0) parts.push(`## Open Questions\n${openQuestions.map((q) => `- ${q}`).join('\n')}\n`)
      textToCopy = parts.join('\n')
    }

    if (textToCopy) {
      await navigator.clipboard.writeText(textToCopy)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }

  return (
    <section className="bg-white border border-gray-200 rounded-xl p-5 shadow-2xs">
      {/* Card Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-4 border-b border-gray-100">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-gray-100 border border-gray-200 flex items-center justify-center text-gray-700 shrink-0">
            <BookOpen className="w-4 h-4" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-gray-900 leading-tight">
              Meeting Notes
            </h3>
            <p className="text-xs text-gray-500 mt-0.5">
              Structured summary, key decisions, action items, and open questions.
            </p>
          </div>
        </div>

        {hasAnyData && (
          <div className="flex items-center gap-2 self-start sm:self-auto">
            <button
              type="button"
              onClick={handleCopyNotes}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 active:bg-gray-100 rounded-md transition-colors cursor-pointer shadow-2xs"
              title="Copy notes as Markdown"
            >
              {copied ? (
                <>
                  <Check className="w-3.5 h-3.5 text-emerald-600" />
                  <span>Copied</span>
                </>
              ) : (
                <>
                  <Copy className="w-3.5 h-3.5 text-gray-500" />
                  <span>Copy Notes</span>
                </>
              )}
            </button>

            <button
              type="button"
              onClick={() => setViewingRawModal(true)}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 active:bg-gray-100 rounded-md transition-colors cursor-pointer shadow-2xs"
              title="View full Markdown / raw text"
            >
              <span>View Markdown</span>
              <ExternalLink className="w-3 h-3 text-gray-400" />
            </button>

            {onDeleteNote && rawNoteObj?.id && (
              <button
                type="button"
                onClick={() => onDeleteNote(rawNoteObj.id)}
                className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors"
                title="Delete note"
                aria-label="Delete note"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        )}
      </div>

      {/* Generating State */}
      {isGenerating ? (
        <div className="py-12 px-4 text-center space-y-3">
          <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center mx-auto text-gray-900 animate-pulse">
            <Loader2 className="w-5 h-5 animate-spin" />
          </div>
          <div>
            <p className="text-xs md:text-sm font-semibold text-gray-900">
              Generating AI Meeting Notes...
            </p>
            <p className="text-xs text-gray-500 mt-1 max-w-sm mx-auto">
              Groq LLM is analyzing the transcripts to extract summary, decisions, action items, and open questions.
            </p>
          </div>
        </div>
      ) : hasAnyData ? (
        <div className="mt-5 space-y-5">
          {/* 1. Meeting Summary */}
          {meetingSummary && (
            <div className="p-4 bg-gray-50/70 border border-gray-200/90 rounded-xl space-y-1.5">
              <h4 className="text-xs font-bold text-gray-900 uppercase tracking-wider flex items-center gap-1.5">
                <Sparkles className="w-3.5 h-3.5 text-gray-700" />
                Meeting Summary
              </h4>
              <p className="text-xs md:text-sm text-gray-800 leading-relaxed font-sans">
                {meetingSummary}
              </p>
            </div>
          )}

          {/* 2. Key Discussion Points */}
          {keyPoints.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-xs font-bold text-gray-900 uppercase tracking-wider flex items-center gap-1.5">
                <ListChecks className="w-3.5 h-3.5 text-gray-700" />
                Key Discussion Points
              </h4>
              <ul className="space-y-2 pl-1">
                {keyPoints.map((pt, i) => (
                  <li key={i} className="text-xs md:text-sm text-gray-700 flex items-start gap-2.5">
                    <span className="w-1.5 h-1.5 rounded-full bg-gray-400 mt-2 shrink-0" />
                    <span className="leading-relaxed">{pt}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* 3. Decisions Made */}
          {decisions.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-xs font-bold text-gray-900 uppercase tracking-wider flex items-center gap-1.5">
                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
                Decisions Made
              </h4>
              <ul className="space-y-2">
                {decisions.map((dec, i) => (
                  <li
                    key={i}
                    className="p-3 bg-emerald-50/50 border border-emerald-100 rounded-lg text-xs md:text-sm text-emerald-950 flex items-start gap-2.5 leading-relaxed"
                  >
                    <Check className="w-4 h-4 text-emerald-600 shrink-0 mt-0.5" />
                    <span>{dec}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* 4. Action Items Table */}
          {actionItems.length > 0 && (
            <div className="space-y-2.5">
              <h4 className="text-xs font-bold text-gray-900 uppercase tracking-wider flex items-center gap-1.5">
                <Clock className="w-3.5 h-3.5 text-gray-700" />
                Action Items
              </h4>
              <div className="border border-gray-200 rounded-lg overflow-x-auto bg-white">
                <table className="w-full text-left text-xs min-w-[500px]">
                  <thead className="bg-gray-50 border-b border-gray-200 text-gray-600 font-semibold uppercase text-[10px] tracking-wider">
                    <tr>
                      <th className="py-2.5 px-3.5">Task Description</th>
                      <th className="py-2.5 px-3.5 w-44">Assigned Owner</th>
                      <th className="py-2.5 px-3.5 w-36">Deadline</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {actionItems.map((item, i) => {
                      const task = typeof item === 'object' ? item.task : item
                      const owner = typeof item === 'object' ? item.owner : 'Not specified'
                      const deadline = typeof item === 'object' ? item.deadline : 'Not specified'

                      return (
                        <tr key={i} className="hover:bg-gray-50/60 transition-colors">
                          <td className="py-2.5 px-3.5 text-gray-900 font-medium leading-relaxed">
                            {task}
                          </td>
                          <td className="py-2.5 px-3.5 text-gray-600">
                            <span className="inline-block px-2 py-0.5 rounded bg-gray-100 border border-gray-200 text-gray-700 font-mono text-[11px]">
                              {owner || 'Not specified'}
                            </span>
                          </td>
                          <td className="py-2.5 px-3.5 text-gray-600">
                            <span className="text-[11px] text-gray-500 font-medium">
                              {deadline || 'Not specified'}
                            </span>
                          </td>
                        </tr>
                      )
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* 5. Open Questions */}
          {openQuestions.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-xs font-bold text-gray-900 uppercase tracking-wider flex items-center gap-1.5">
                <HelpCircle className="w-3.5 h-3.5 text-amber-600" />
                Open Questions
              </h4>
              <ul className="space-y-1.5 pl-1">
                {openQuestions.map((q, i) => (
                  <li key={i} className="text-xs md:text-sm text-gray-700 flex items-start gap-2">
                    <span className="text-amber-500 font-bold shrink-0 mt-0.5">•</span>
                    <span className="leading-relaxed">{q}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Fallback Markdown Display if not structured */}
          {!meetingSummary && markdownText && (
            <div className="p-4 bg-gray-50 rounded-lg text-xs md:text-sm text-gray-800 whitespace-pre-wrap leading-relaxed">
              {markdownText}
            </div>
          )}
        </div>
      ) : (
        <div className="mt-4 p-8 border border-dashed border-gray-200 rounded-lg text-center bg-gray-50/50">
          <BookOpen className="w-6 h-6 text-gray-400 mx-auto mb-2" />
          <p className="text-xs font-semibold text-gray-700">No notes yet</p>
          <p className="text-xs text-gray-400 mt-1 max-w-sm mx-auto leading-relaxed">
            Click <span className="font-medium text-gray-800">Generate Notes</span> above after transcribing your audio to produce AI meeting notes.
          </p>
        </div>
      )}

      {/* Full Raw Markdown Viewer Modal */}
      {viewingRawModal && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-2xs"
          role="dialog"
          aria-modal="true"
          onClick={() => setViewingRawModal(false)}
        >
          <div
            className="w-full max-w-2xl bg-white border border-gray-200 rounded-xl shadow-2xl p-6 max-h-[85vh] flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-start justify-between pb-3 border-b border-gray-100">
              <div>
                <h3 className="text-sm md:text-base font-semibold text-gray-900">
                  Meeting Notes (Markdown View)
                </h3>
                <p className="text-xs text-gray-400 mt-0.5">
                  Raw markdown formatted output from Groq LLM
                </p>
              </div>
              <button
                type="button"
                onClick={() => setViewingRawModal(false)}
                className="p-1 text-gray-400 hover:text-gray-700 rounded-md hover:bg-gray-100"
                aria-label="Close"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto py-4 text-xs font-mono text-gray-800 leading-relaxed whitespace-pre-wrap bg-gray-50 p-4 rounded-lg my-2 select-text">
              {markdownText || 'No markdown text available.'}
            </div>

            <div className="pt-3 border-t border-gray-100 flex items-center justify-between">
              <button
                type="button"
                onClick={handleCopyNotes}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-200 rounded-md hover:bg-gray-50 cursor-pointer"
              >
                {copied ? (
                  <>
                    <Check className="w-3.5 h-3.5 text-emerald-600" />
                    <span>Copied</span>
                  </>
                ) : (
                  <>
                    <Copy className="w-3.5 h-3.5 text-gray-500" />
                    <span>Copy Markdown</span>
                  </>
                )}
              </button>

              <button
                type="button"
                onClick={() => setViewingRawModal(false)}
                className="px-4 py-1.5 text-xs font-medium text-white bg-gray-900 hover:bg-black rounded-md cursor-pointer"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  )
}
